namespace ghidra.framework.main.datatree;







using docking;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.util;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * Dialog to prompt user to save files before adding files to source control
 * or checking in files.
 */
public class ChangedFilesDialog : DialogComponentProvider {

	private List<DomainFile> fileList;
	private DomainFilesPanel filePanel;
	private PluginTool tool;
	private bool saveSelected;

	/** 
	 * Constructor 
	 * @param tool tool to execute task and log messages in status window
	 * @param list list of domain files that have changes
	 */
	public ChangedFilesDialog(PluginTool tool, List<DomainFile> list) : base("Save Changed Files?", true)
    {
		this.tool = tool;
		this.fileList = list;
		addWorkPanel(buildMainPanel());

		JButton saveButton = new JButton("Save");
		saveButton.addActionListener(e => save());
		saveButton.setToolTipText("Save files that have selected check boxes");
		saveButton.getAccessibleContext().setAccessibleName("Save");
		addButton(saveButton);
		addCancelButton();
	}

	/**
	 * Set the tool tip on the cancel button.
	 * @param toolTip tool tip to set on the cancel button
	 */
	public void setCancelToolTipText(string toolTip) {
		setCancelToolTip(toolTip);
	}

	/**
	 * Show ChangedFilesDialog.
	 * @return whether the save button was selected; return false if the user
	 * canceled
	 */
	public bool showDialog() {
		saveSelected = false;
		tool.showDialog(this);
		return saveSelected;
	}

	private JPanel buildMainPanel() {
		JPanel outerPanel = new JPanel(new BorderLayout());
		outerPanel.setBorder(BorderFactory.createEmptyBorder(5, 5, 0, 5));

		filePanel = new DomainFilesPanel(fileList, "Changed Files");
		filePanel.getAccessibleContext().setAccessibleName("Files");
		outerPanel.add(filePanel, BorderLayout.CENTER);

		outerPanel.getAccessibleContext().setAccessibleName("Changed Files");
		return outerPanel;
	}

	private void save() {
		saveSelected = true;
		DomainFile[] files = filePanel.getSelectedDomainFiles();
		if (files.length > 0) {
			SaveTask task = new SaveTask(files);
			tool.execute(task);
		}
		else {
			close();
		}
	}

	/* @Override */
	protected void cancelCallback() {
		close();
	}

	private class SaveTask : Task {
		private DomainFile[] files;

		SaveTask(DomainFile[] files) : base(files.length > 1 ? "Saving Files..." : "Saving File", true, true, true)
    {
			this.files = files;
		}

		/* @Override */
		public void run(TaskMonitor monitor) {
			foreach (DomainFile file in files) {
				if (monitor.isCancelled()) {
					break;
				}
				string name = file.getName();
				monitor.setProgress(0);
				monitor.setMessage("Saving " + name);
				Msg.info(this, "Successfully saved file: " + name);
				try {
					file.save(monitor);
				}
				catch (CancelledException e) {
					return;
				}
				catch (IOException e) {
					Msg.showError(this, tool.getToolFrame(), "Error Saving File",
						"IO Exception while saving " + name, e);
				}
			}
			if (monitor.isCancelled()) {
				saveSelected = false;
			}
			Swing.runLater(() => this.close());
		}
	}

}
